/* Statecharts for the documentation site ------------------------------------
 *
 * Two kinds of chart are drawn in the browser with Mermaid 12 (ELK layout):
 *
 *  1. ```mermaid fenced blocks (export examples in the guides) become a
 *     <figure class="statechart"> with a Full screen viewer.
 *  2. <div class="stately" data-machine="KEY" data-title="…"> markers (one per
 *     machine in the guides and the example gallery) are drawn from
 *     /assets/data/diagrams.json, which holds Stately-style Mermaid for every
 *     key (generated by scripts/place_stately_embeds.py).  Each figure keeps an
 *     "Open in Stately ↗" link to the editor page for the same machine.
 *
 * Statechart colours come from CSS variables in style.css, so the theme
 * toggle needs no re-render for them. Mermaid bakes its own palette into the
 * SVG it draws, though, and sequence/flowchart fences are coloured only by
 * that palette (no `--sc-*` rule reaches their actors or message text), so
 * those figures are redrawn whenever the theme changes.
 *
 * Tooling hook: window.xsmDiagrams = { ready, renderAll, renderInto, figures }
 * is used by scripts/check_diagrams.py to render every chart headlessly and
 * check it for overlapping or clipped elements.
 */
const MERMAID_URL = 'https://cdn.jsdelivr.net/npm/mermaid@12.3.0/dist/mermaid.esm.min.mjs';
let mermaid = null; // loaded in start(); null when the CDN is unreachable

const DATA_URL = new URL('../data/diagrams.json', import.meta.url);
const FETCH_TIMEOUT_MS = 20000;
const EDITOR_URL = 'https://stately.ai/registry/editor/';
const EXPAND_ICON = '<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M2 6V2h4M14 6V2h-4M2 10v4h4M14 10v4h-4"/></svg>';

function editorUrl(project, id) {
  return EDITOR_URL + encodeURIComponent(project) + '?mode=design&machineId=' + encodeURIComponent(id);
}

function editorLink(project, id) {
  const link = document.createElement('a');
  link.className = 'statechart-open';
  link.href = editorUrl(project, id);
  link.target = '_blank';
  link.rel = 'noopener noreferrer';
  link.textContent = 'Open in Stately ↗';
  return link;
}

/** Build the figure every chart lives in; the renderer fills `.statechart-canvas`. */
function buildFigure(kind, title, link, minHeight) {
  const fig = document.createElement('figure');
  fig.className = 'statechart statechart-' + kind + ' is-pending';
  fig.setAttribute('data-kind', kind);
  if (minHeight) fig.style.setProperty('--statechart-min', minHeight + 'px');
  const button = document.createElement('button');
  button.type = 'button';
  button.className = 'statechart-expand';
  button.disabled = true;
  button.setAttribute('aria-label', 'View ' + title + ' full screen');
  button.innerHTML = EXPAND_ICON;
  button.appendChild(document.createTextNode('Full screen'));
  const canvas = document.createElement('div');
  canvas.className = 'statechart-canvas';
  canvas.setAttribute('aria-busy', 'true');
  const caption = document.createElement('figcaption');
  const name = document.createElement('span');
  name.className = 'statechart-name';
  name.textContent = title;
  caption.appendChild(name);
  if (link) {
    const actions = document.createElement('span');
    actions.className = 'statechart-actions';
    actions.appendChild(link);
    caption.appendChild(actions);
  }
  fig.append(button, canvas, caption);
  return fig;
}

/** Read the `--sc-*` palette the stylesheet resolves for the current theme. */
function palette() {
  const probe = document.createElement('div');
  probe.className = 'statechart';
  probe.setAttribute('aria-hidden', 'true');
  probe.style.cssText = 'position:absolute;left:-9999px;top:0;width:1px;height:1px;visibility:hidden;';
  document.body.appendChild(probe);
  const style = getComputedStyle(probe);
  const read = name => style.getPropertyValue(name).trim();
  const values = {
    canvas: read('--sc-canvas'), text: read('--sc-text'), node: read('--sc-node'),
    nodeBorder: read('--sc-node-border'), edge: read('--sc-edge'), pill: read('--sc-pill'),
    chip: read('--sc-chip'), chipBorder: read('--sc-chip-border'), cluster: read('--sc-cluster')
  };
  probe.remove();
  return values;
}

/**
 * Mermaid's theme for the current theme, built from the same palette the
 * stylesheet gives statecharts so the two can never drift. Sequence diagrams
 * and flowcharts are coloured only by these values: `--sc-*` rules do not
 * reach their actors, signals or message text.
 */
function themeVariables() {
  const p = palette();
  return {
    fontFamily: 'Space Grotesk, ui-sans-serif, system-ui', fontSize: '14px',
    background: 'transparent',
    //_nodes, clusters and edges (flowchart, class, ER…)
    primaryColor: p.node, primaryTextColor: p.text, primaryBorderColor: p.nodeBorder,
    secondaryColor: p.chip, secondaryTextColor: p.text, secondaryBorderColor: p.chipBorder,
    tertiaryColor: p.cluster, tertiaryTextColor: p.text, tertiaryBorderColor: p.nodeBorder,
    mainBkg: p.node, nodeBorder: p.nodeBorder, lineColor: p.edge, textColor: p.text,
    clusterBkg: p.cluster, clusterBorder: p.nodeBorder,
    edgeLabelBackground: 'transparent', labelTextColor: p.text,
    //_state diagrams
    transitionColor: p.edge, transitionLabelColor: p.text,
    stateBkg: p.node, stateLabelColor: p.text, altBackground: p.cluster,
    compositeBackground: p.cluster, compositeTitleBackground: p.cluster,
    noteBkgColor: p.chip, noteBorderColor: p.chipBorder, noteTextColor: p.text,
    //_sequence diagrams
    actorBkg: p.node, actorBorder: p.nodeBorder, actorTextColor: p.text,
    actorLineColor: p.edge, signalColor: p.edge, signalTextColor: p.text,
    labelBoxBkgColor: p.pill, labelBoxBorderColor: p.chipBorder,
    loopTextColor: p.text, activationBkgColor: p.chip,
    activationBorderColor: p.nodeBorder, sequenceNumberColor: p.canvas
  };
}

function configureMermaid() {
  // 📝 Structure only in the fixed part; colour is the palette for the theme
  //    in force right now (see `themeVariables`). ELK (Mermaid 12's default)
  //    routes transitions orthogonally, the way the Stately editor draws them.
  mermaid.initialize({
    startOnLoad: false, theme: 'base', securityLevel: 'loose', suppressErrorRendering: true, layout: 'elk',
    state: { padding: 16, nodeSpacing: 48, rankSpacing: 56, useMaxWidth: true },
    flowchart: { padding: 14, nodeSpacing: 36, rankSpacing: 44, useMaxWidth: true, htmlLabels: true },
    themeVariables: themeVariables()
  });
}

/**
 * Mermaid fixes themeVariables into the SVG when it draws, so a theme switch
 * must redraw what is on screen. Statecharts would survive on CSS alone,
 * fences would keep the old palette (pale text on a light figure).
 */
/**
 * 📱 Below 720px a chart keeps its natural size and the figure scrolls
 * sideways, the way a wide code block does: Mermaid emits width="100%", so
 * shrinking to the column drew a 2,300px chart at 16% and its labels at
 * about 2px. Above that the chart scales to the column as before.
 */
function fitViewport(svg) {
  if (!svg) return;
  if (innerWidth <= 720) {
    const vb = svg.viewBox && svg.viewBox.baseVal;
    if (vb && vb.width) {
      svg.style.width = vb.width + 'px';
      svg.style.height = vb.height + 'px';
      svg.style.maxWidth = 'none';
      return;
    }
  }
  svg.style.width = '';
  svg.style.height = '';
  svg.style.maxWidth = '';
}

function watchTheme() {
  const root = document.documentElement;
  let applied = root.getAttribute('data-theme');
  new MutationObserver(() => {
    const next = root.getAttribute('data-theme');
    if (next === applied || !mermaid) return;
    applied = next;
    configureMermaid();
    figures.filter(d => d.fig.querySelector('.statechart-canvas svg')).forEach(render);
    if (activeDiagram) refreshViewer(true);
  }).observe(root, { attributes: true, attributeFilter: ['data-theme'] });
}

const figures = [];
let sequence = 0;
let queue = Promise.resolve();

/** Render one figure's Mermaid source into its canvas (serialised). */
function render(diagram) {
  if (diagram.pending) return diagram.pending;
  diagram.pending = queue = queue.then(async () => {
    const surface = diagram.fig.querySelector('.statechart-canvas');
    const button = diagram.fig.querySelector('.statechart-expand');
    try {
      if (!mermaid) throw new Error('Mermaid did not load');
      const { svg } = await mermaid.render('sc-' + (++sequence), diagram.source);
      surface.innerHTML = svg;
      // Cosmetic passes: a geometry quirk must never take a drawn chart away.
      try {
        settleLabels(surface.querySelector('svg'));
        fitMachineBox(surface.querySelector('svg'));
        decorateStates(surface.querySelector('svg'));
        fitViewport(surface.querySelector('svg'));
      } catch (_) { /* keep the chart as Mermaid drew it */ }
      diagram.fig.classList.remove('is-pending', 'is-failed');
      diagram.fig.setAttribute('data-rendered', 'true');
      button.disabled = false;
      if (activeDiagram === diagram) refreshViewer(false);
    } catch (error) {
      diagram.fig.classList.remove('is-pending');
      diagram.fig.classList.add('is-failed');
      diagram.fig.setAttribute('data-rendered', 'error');
      diagram.error = String(error && error.message || error);
      surface.innerHTML = '';
      if (diagram.kind === 'fence') {
        const pre = document.createElement('pre');
        pre.textContent = diagram.source;
        surface.appendChild(pre);
      } else {
        const note = document.createElement('p');
        note.className = 'statechart-error';
        note.textContent = mermaid
          ? 'This diagram could not be drawn in this browser.'
          : 'The diagram library did not load; use "Open in Stately" to view this machine.';
        surface.appendChild(note);
      }
      button.disabled = true;
      if (activeDiagram === diagram) closeViewer();
    } finally {
      surface.removeAttribute('aria-busy');
    }
  });
  return diagram.pending;
}

/* ---------------------------------------------------------- label settling -- */
function userBox(svg, element) {
  const inverse = svg.getScreenCTM().inverse();
  const r = element.getBoundingClientRect();
  const a = new DOMPoint(r.left, r.top).matrixTransform(inverse);
  const b = new DOMPoint(r.right, r.bottom).matrixTransform(inverse);
  return { x: Math.min(a.x, b.x), y: Math.min(a.y, b.y), w: Math.abs(b.x - a.x), h: Math.abs(b.y - a.y) };
}

function pathPoint(svg, path, length) {
  const inverse = svg.getScreenCTM().inverse();
  const p = path.getPointAtLength(length).matrixTransform(path.getScreenCTM());
  return new DOMPoint(p.x, p.y).matrixTransform(inverse);
}

function overlaps(a, b, gap) {
  return !(a.x + a.w + gap <= b.x || b.x + b.w + gap <= a.x || a.y + a.h + gap <= b.y || b.y + b.h + gap <= a.y);
}

function shiftGroup(group, dx, dy) {
  const consolidated = group.transform.baseVal.consolidate();
  const e = consolidated ? consolidated.matrix.e : 0, f = consolidated ? consolidated.matrix.f : 0;
  group.setAttribute('transform', 'translate(' + (e + dx) + ', ' + (f + dy) + ')');
}

/**
 * A composite's title band, across its full width: the strip of its outer
 * rectangle that the inner one leaves uncovered (the title's height when
 * there is no inner rectangle).
 */
function bandBox(svg, cluster) {
  const own = selector => [...cluster.querySelectorAll(selector)].find(el => el.closest('g.statediagram-cluster') === cluster) || null;
  const outer = own('rect.outer') || own('rect');
  if (!outer) return null;
  const box = userBox(svg, outer);
  const inner = own('rect.inner'), title = own('g.cluster-label');
  let height = inner ? userBox(svg, inner).y - box.y : 0;
  if (!(height > 0) && title) { const t = userBox(svg, title); height = t.h ? t.y + t.h - box.y : 0; }
  return height > 0 && box.w > 0 ? { x: box.x, y: box.y, w: box.w, h: height } : null;
}

/**
 * Mermaid centres every transition label on its path, which in a dense chart
 * can land on a state box or on another label. Slide such a label along its
 * own transition, then beside it, to the first free spot. Runs once, right
 * after the SVG is in the page, in SVG user units (so CSS scaling is fine).
 */
function settleLabels(svg) {
  if (!svg || !svg.getScreenCTM()) return;
  // Clear space a label keeps from a state, a title band or another label;
  // from another transition's line; from a composite border (either side).
  const GAP = 6, LINE_GAP = 6, EDGE_GAP = 4;
  const ARROW = 16; // the last stretch of a transition, where its arrowhead is drawn
  const obstacles = [];
  svg.querySelectorAll('g.node').forEach(node => {
    const shape = node.querySelector(':scope > rect, :scope > g > rect, :scope > circle, :scope > polygon') || node;
    obstacles.push(userBox(svg, shape));
  });
  svg.querySelectorAll('g.statediagram-cluster').forEach(cluster => {
    const band = bandBox(svg, cluster);
    if (band) obstacles.push(band);
  });
  const paths = new Map();
  svg.querySelectorAll('path.transition[data-id]').forEach(p => paths.set(p.getAttribute('data-id'), p));
  // Every other transition's line, sampled: a label must not sit on one.
  const sampled = new Map();
  paths.forEach((p, id) => {
    const points = [], length = p.getTotalLength();
    for (let s = 0; s <= length; s += 6) points.push(pathPoint(svg, p, s));
    points.push(pathPoint(svg, p, length));
    sampled.set(id, points);
  });
  const near = (pt, box, gap) => pt.x > box.x - gap && pt.x < box.x + box.w + gap && pt.y > box.y - gap && pt.y < box.y + box.h + gap;
  const crossed = (box, ownId) => {
    for (const [id, points] of sampled) {
      if (id === ownId) continue;
      if (points.some(pt => near(pt, box, LINE_GAP))) return true;
    }
    return false;
  };
  // Nor does a label cover the arrowhead of its own transition.
  const onArrow = (box, ownId) => {
    const points = ownId ? sampled.get(ownId) : null;
    if (!points || points.length < 2) return false;
    const end = points[points.length - 1];
    return points.some(pt => Math.hypot(pt.x - end.x, pt.y - end.y) <= ARROW && near(pt, box, 5));
  };
  // Composite borders: a label sits inside a box or outside it, never across.
  const clusterBoxes = [...svg.querySelectorAll('g.statediagram-cluster')]
    .map(cluster => cluster.querySelector('rect.outer') || cluster.querySelector('rect'))
    .filter(Boolean).map(rect => userBox(svg, rect));
  const inside = (box, c, gap) => box.x >= c.x + gap && box.y >= c.y + gap
    && box.x + box.w <= c.x + c.w - gap && box.y + box.h <= c.y + c.h - gap;
  // Clear of the border on one side or the other: never on it, never touching it.
  const straddles = box => clusterBoxes.some(c => overlaps(box, c, EDGE_GAP) && !inside(box, c, EDGE_GAP));
  // The machine box: a label must not hang outside it.
  let bounds = null;
  clusterBoxes.forEach(box => { if (!bounds || box.w * box.h > bounds.w * bounds.h) bounds = box; });
  const within = box => !bounds || inside(box, bounds, EDGE_GAP);
  const placed = [];
  const free = (box, ownId) => !obstacles.some(o => overlaps(box, o, GAP)) && !placed.some(p => overlaps(box, p, GAP))
    && !straddles(box) && !crossed(box, ownId) && !onArrow(box, ownId);
  svg.querySelectorAll('g.edgeLabel').forEach(group => {
    if (!(group.textContent || '').trim()) return;
    const inner = group.querySelector('.xsm-pill, .labelBkg') || group;
    const box = userBox(svg, inner);
    const label = group.querySelector('g.label');
    const ownId = label ? label.getAttribute('data-id') : null;
    if (free(box, ownId) && within(box)) { placed.push(box); return; }
    const clear = b => free(b, ownId);
    let target = null;
    if (bounds && !within(box)) {
      // Hanging over the machine border: the smallest move that brings it inside.
      const clamped = {
        x: Math.min(Math.max(box.x, bounds.x + EDGE_GAP + 1), bounds.x + bounds.w - box.w - EDGE_GAP - 1),
        y: Math.min(Math.max(box.y, bounds.y + EDGE_GAP + 1), bounds.y + bounds.h - box.h - EDGE_GAP - 1),
        w: box.w, h: box.h
      };
      if (clear(clamped)) target = clamped;
    }
    const path = ownId ? paths.get(ownId) : null;
    if (!target && path) {
      const length = path.getTotalLength();
      const centred = (point) => ({ x: point.x - box.w / 2, y: point.y - box.h / 2, w: box.w, h: box.h });
      // Along the line, working outwards from its middle.
      const fractions = [0.5];
      for (let step = 0.03; step <= 0.42; step += 0.03) fractions.push(0.5 - step, 0.5 + step);
      for (const fraction of fractions) {
        const candidate = centred(pathPoint(svg, path, fraction * length));
        if (clear(candidate)) { target = candidate; break; }
      }
      if (!target) {
        // Off-centre on the line, then beside it (touching): a label must
        // stay with its transition. The smallest shift that frees it wins.
        for (const share of [0.35, 0.7, 1]) {
          for (const fraction of fractions) {
            const at = fraction * length;
            const p = pathPoint(svg, path, at), q = pathPoint(svg, path, Math.min(length, at + 2));
            const dx = q.x - p.x, dy = q.y - p.y, norm = Math.hypot(dx, dy) || 1;
            const nx = -dy / norm, ny = dx / norm;
            const reach = share * (Math.abs(nx) * (box.w / 2) + Math.abs(ny) * (box.h / 2) + 6);
            for (const side of [1, -1]) {
              const candidate = centred({ x: p.x + side * nx * reach, y: p.y + side * ny * reach });
              if (clear(candidate)) { target = candidate; break; }
            }
            if (target) break;
          }
          if (target) break;
        }
      }
    }
    if (target) {
      shiftGroup(group, target.x - box.x, target.y - box.y);
      placed.push(target);
    } else {
      placed.push(box);
    }
  });
}

/**
 * Stately draws a state that has rows as a header band over a darker body.
 * Mermaid gives such a state one rectangle and a divider line, so a path with
 * rounded top corners is laid over the title area to form the band.
 */
function decorateStates(svg) {
  svg.querySelectorAll('g.node.statediagram-state').forEach(node => {
    const rect = node.querySelector('rect.title-state');
    const divider = node.querySelector('line.divider');
    if (!rect || !divider || node.querySelector('path.xsm-head')) return;
    const x = parseFloat(rect.getAttribute('x')), y = parseFloat(rect.getAttribute('y'));
    const w = parseFloat(rect.getAttribute('width')), h = parseFloat(divider.getAttribute('y1')) - y;
    if (!(w > 0 && h > 0)) return;
    const r = Math.min(6, h / 2);
    const head = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    head.setAttribute('class', 'xsm-head');
    head.setAttribute('d', `M${x + r},${y} h${w - 2 * r} a${r},${r} 0 0 1 ${r},${r} v${h - r} h${-w} v${-(h - r)} a${r},${r} 0 0 1 ${r},${-r} z`);
    rect.parentNode.insertBefore(head, rect.nextSibling);
  });
}

/**
 * ELK sizes a composite from its states only, so a transition label on an
 * outer edge can hang over the machine border. Widen the machine box (the
 * largest composite) until every label and state sits inside it, keep its
 * title centred, and let the SVG canvas follow.
 */
function fitMachineBox(svg) {
  if (!svg || !svg.getScreenCTM()) return;
  const PAD = 10;
  const clusters = [...svg.querySelectorAll('g.statediagram-cluster')]
    .map(cluster => ({ cluster, rect: cluster.querySelector('rect.outer') || cluster.querySelector('rect') }))
    .filter(entry => entry.rect)
    .map(entry => ({ ...entry, box: userBox(svg, entry.rect) }))
    .sort((a, b) => b.box.w * b.box.h - a.box.w * a.box.h);
  const root = clusters[0];
  if (!root) return;
  root.cluster.classList.add('xsm-root'); // the machine box: Stately leaves its body the canvas colour
  let minX = root.box.x, minY = root.box.y, maxX = root.box.x + root.box.w, maxY = root.box.y + root.box.h;
  const include = element => {
    const b = userBox(svg, element);
    if (!b.w || !b.h) return;
    minX = Math.min(minX, b.x - PAD); minY = Math.min(minY, b.y - PAD);
    maxX = Math.max(maxX, b.x + b.w + PAD); maxY = Math.max(maxY, b.y + b.h + PAD);
  };
  svg.querySelectorAll('g.edgeLabel').forEach(group => {
    if ((group.textContent || '').trim()) include(group.querySelector('.xsm-pill, .labelBkg') || group);
  });
  svg.querySelectorAll('g.node').forEach(node => {
    include(node.querySelector(':scope > rect, :scope > g > rect, :scope > circle') || node);
  });
  const left = Math.max(0, root.box.x - minX), top = Math.max(0, root.box.y - minY);
  const right = Math.max(0, maxX - root.box.x - root.box.w), bottom = Math.max(0, maxY - root.box.y - root.box.h);
  if (!left && !top && !right && !bottom) return;
  root.cluster.querySelectorAll(':scope > rect, :scope > g > rect').forEach(rect => {
    const outer = rect.classList.contains('outer');
    const x = parseFloat(rect.getAttribute('x')) || 0, y = parseFloat(rect.getAttribute('y')) || 0;
    const w = parseFloat(rect.getAttribute('width')) || 0, h = parseFloat(rect.getAttribute('height')) || 0;
    rect.setAttribute('x', x - left);
    rect.setAttribute('width', w + left + right);
    rect.setAttribute('height', h + bottom + (outer ? top : 0));
    if (outer && top) rect.setAttribute('y', y - top);
  });
  const title = root.cluster.querySelector(':scope > g.cluster-label');
  if (title) shiftGroup(title, (right - left) / 2, -top);
  const bbox = svg.getBBox();
  svg.setAttribute('viewBox', [bbox.x - 4, bbox.y - 4, bbox.width + 8, bbox.height + 8].join(' '));
  svg.style.maxWidth = (bbox.width + 8) + 'px';
}

/* ---------------------------------------------------------------- viewer -- */
// One modal viewer. Real SVG dimensions keep both zoomed edges reachable.
const lb = document.createElement('div');
lb.className = 'statechart-lightbox';
lb.setAttribute('role', 'dialog'); lb.setAttribute('aria-modal', 'true');
lb.setAttribute('aria-label', 'Diagram'); lb.setAttribute('aria-hidden', 'true');
lb.setAttribute('inert', '');
lb.innerHTML = '<div class="statechart-lightbox-bar"><span class="lb-title">statechart</span><div class="actions">'
  + '<button type="button" data-zoom="-1" aria-label="Zoom out">−</button><button type="button" data-zoom="0" aria-label="Fit diagram to screen" title="Fit diagram to screen">Fit</button>'
  + '<button type="button" data-zoom="1" aria-label="Zoom in">+</button><button type="button" data-close aria-label="Close">Close · Esc</button>'
  + '</div></div><div class="statechart-lightbox-canvas statechart-canvas" tabindex="0" role="region" aria-label="Diagram; use arrow keys to scroll when zoomed"></div>';
const canvas = lb.querySelector('.statechart-lightbox-canvas'), zoomLabel = lb.querySelector('[data-zoom="0"]');
const closeButton = lb.querySelector('[data-close]');
const backgroundState = new Map();
let scale = 1, naturalWidth = 1, naturalHeight = 1;
let activeDiagram = null, lastFocus = null, canvasSize = '', viewportSize = '';
let fitted = true;

function isolate(element) {
  if (element === lb || !(element instanceof HTMLElement) || backgroundState.has(element)) return;
  backgroundState.set(element, element.hasAttribute('inert'));
  element.setAttribute('inert', '');
}

function fitScale() {
  const padding = getComputedStyle(canvas);
  const width = Math.max(1, canvas.clientWidth - parseFloat(padding.paddingLeft) - parseFloat(padding.paddingRight));
  const height = Math.max(1, canvas.clientHeight - parseFloat(padding.paddingTop) - parseFloat(padding.paddingBottom));
  return Math.min(1, width / naturalWidth, height / naturalHeight);
}

function applyZoom() {
  const svg = canvas.querySelector('svg');
  if (!svg) return;
  svg.style.width = (naturalWidth * scale) + 'px';
  svg.style.height = (naturalHeight * scale) + 'px';
  zoomLabel.textContent = Math.round(scale * 100) + '%';
}

function fitDiagram() {
  if (!activeDiagram) return;
  fitted = true;
  scale = fitScale();
  applyZoom();
  canvas.scrollLeft = 0; canvas.scrollTop = 0;
  const bounds = canvas.getBoundingClientRect();
  canvasSize = bounds.width + ':' + bounds.height;
  viewportSize = innerWidth + ':' + innerHeight;
}

function changeZoom(direction) {
  if (!direction) { fitDiagram(); return; }
  fitted = false;
  scale = Math.min(4, Math.max(Math.min(.1, fitScale()), scale * (direction > 0 ? 1.25 : .8)));
  applyZoom();
}

function refreshViewer(reset) {
  const svg = activeDiagram && activeDiagram.fig.querySelector('.statechart-canvas svg');
  if (!svg) return;
  const clone = svg.cloneNode(true);
  clone.removeAttribute('width'); clone.removeAttribute('height'); clone.style.maxWidth = 'none';
  const vb = (svg.getAttribute('viewBox') || '').trim().split(/[\s,]+/).map(Number);
  naturalWidth = vb.length === 4 && vb[2] > 0 ? vb[2] : Math.max(1, svg.getBoundingClientRect().width);
  naturalHeight = vb.length === 4 && vb[3] > 0 ? vb[3] : Math.max(1, svg.getBoundingClientRect().height);
  canvas.replaceChildren(clone);
  if (reset) fitDiagram();
  else applyZoom();
}

function closeViewer() {
  if (!activeDiagram) return;
  activeDiagram = null;
  backgroundState.forEach((wasInert, element) => element.toggleAttribute('inert', wasInert));
  backgroundState.clear();
  document.body.classList.remove('diagram-open');
  const target = lastFocus && lastFocus.isConnected && !lastFocus.disabled ? lastFocus : document.querySelector('#main-content');
  if (target) target.focus({ preventScroll: true });
  lb.classList.remove('open'); lb.setAttribute('aria-hidden', 'true'); lb.setAttribute('inert', '');
  canvas.replaceChildren();
}

function openViewer(diagram, trigger) {
  if (!diagram.fig.querySelector('.statechart-canvas svg')) return;
  activeDiagram = diagram; lastFocus = trigger;
  lb.querySelector('.lb-title').textContent = diagram.title;
  lb.removeAttribute('inert'); lb.setAttribute('aria-hidden', 'false'); lb.classList.add('open');
  document.body.classList.add('diagram-open');
  refreshViewer(true);
  closeButton.focus({ preventScroll: true });
  [...document.body.children].forEach(isolate);
}

lb.addEventListener('click', e => {
  const b = e.target.closest('button');
  if (!b) { if (e.target === lb || e.target === canvas) closeViewer(); return; }
  if (b.hasAttribute('data-close')) closeViewer();
  else changeZoom(Number(b.dataset.zoom));
});
canvas.addEventListener('wheel', e => {
  if (!e.ctrlKey && !e.metaKey) return;
  e.preventDefault(); changeZoom(e.deltaY < 0 ? 1 : -1);
}, { passive: false });
lb.addEventListener('keydown', e => {
  // Viewer keystrokes must not open search/help underneath the modal.
  e.stopPropagation();
  if (((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') || e.key === '/' || e.key === '?') {
    e.preventDefault(); return;
  }
  if (e.key === 'Escape') { e.preventDefault(); closeViewer(); return; }
  if (e.key !== 'Tab') return;
  const focusable = [...lb.querySelectorAll('button:not(:disabled), [tabindex="0"]')];
  const first = focusable[0], last = focusable[focusable.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
});
document.addEventListener('focusin', e => {
  if (activeDiagram && !lb.contains(e.target)) closeButton.focus({ preventScroll: true });
});
new MutationObserver(records => {
  if (!activeDiagram) return;
  records.forEach(record => record.addedNodes.forEach(node => {
    if (node.parentElement === document.body) isolate(node);
  }));
}).observe(document.body, { childList: true });

function refitOnResize() {
  if (!activeDiagram) return;
  const bounds = canvas.getBoundingClientRect();
  const nextCanvasSize = bounds.width + ':' + bounds.height;
  // Scrollbars or a toolbar reflow must not erase a user's zoom level.
  if (viewportSize !== innerWidth + ':' + innerHeight || (fitted && canvasSize !== nextCanvasSize)) fitDiagram();
  else canvasSize = nextCanvasSize;
}
if ('ResizeObserver' in window) new ResizeObserver(refitOnResize).observe(canvas, { box: 'border-box' });
window.addEventListener('resize', refitOnResize);

let viewportFrame = 0;
window.addEventListener('resize', () => {
  if (viewportFrame) return;
  viewportFrame = requestAnimationFrame(() => {
    viewportFrame = 0;
    document.querySelectorAll('.statechart-canvas svg').forEach(fitViewport);
  });
});

/* ------------------------------------------------------------- discovery -- */
function pageTitle() {
  const heading = document.querySelector('.content h1');
  return (heading && heading.textContent.trim()) || document.title.split(' | ')[0] || 'statechart';
}

function register(diagram) {
  figures.push(diagram);
  const button = diagram.fig.querySelector('.statechart-expand');
  button.addEventListener('click', () => openViewer(diagram, button));
  return diagram;
}

/** ```mermaid fences — runs after main.js (which wraps <pre> in .code-frame). */
function collectFences() {
  const isMermaid = c => c.classList.contains('language-mermaid') ||
    /^\s*(stateDiagram(-v2)?|flowchart|graph|sequenceDiagram)\b/.test(c.textContent);
  const title = pageTitle();
  return [...document.querySelectorAll('pre > code')].filter(isMermaid).map(code => {
    const pre = code.closest('pre');
    const host = pre.closest('.highlighter-rouge') || pre.closest('.highlight') || pre.closest('.code-frame') || pre;
    const fig = buildFigure('fence', 'statechart', null, 0);
    const source = code.textContent;
    host.replaceWith(fig);
    return register({ fig, source, kind: 'fence', title });
  });
}

/** <div class="stately" data-machine="…"> markers → figures drawn from the asset. */
async function collectEmbeds() {
  const hosts = [...document.querySelectorAll('.stately[data-machine]')];
  if (!hosts.length) return [];
  let data = null;
  try {
    const controller = 'AbortController' in window ? new AbortController() : null;
    const timer = setTimeout(() => controller && controller.abort(), FETCH_TIMEOUT_MS);
    const response = await fetch(DATA_URL, controller ? { signal: controller.signal } : undefined);
    clearTimeout(timer);
    if (response.ok) data = await response.json();
  } catch (_) { /* offline: the markers become figures with their editor links */ }
  const machines = data && data.machines && typeof data.machines === 'object' ? data.machines : {};
  const project = data && typeof data.project === 'string' ? data.project : '';
  return hosts.map(host => {
    const key = host.getAttribute('data-machine');
    const entry = machines[key];
    const title = host.getAttribute('data-title') || (entry && entry.title) || key;
    const height = Number(host.getAttribute('data-height'));
    const link = project && entry && typeof entry.id === 'string' ? editorLink(project, entry.id) : null;
    const fig = buildFigure('embed', title, link, Number.isFinite(height) && height > 0 ? height : 0);
    fig.setAttribute('data-machine', key);
    host.replaceWith(fig);
    const diagram = register({ fig, source: entry && typeof entry.mermaid === 'string' ? entry.mermaid : '', kind: 'embed', title, key });
    if (!diagram.source) {
      fig.classList.remove('is-pending'); fig.classList.add('is-failed');
      fig.setAttribute('data-rendered', 'error');
      diagram.error = 'no diagram for ' + key;
      const note = document.createElement('p');
      note.className = 'statechart-error';
      note.textContent = 'Diagram data unavailable.';
      fig.querySelector('.statechart-canvas').replaceChildren(note);
      fig.querySelector('.statechart-canvas').removeAttribute('aria-busy');
    }
    return diagram;
  });
}

/** Draw embeds as they approach the viewport (the gallery holds dozens). */
function observe(diagrams) {
  const pending = diagrams.filter(d => d.source);
  if (!('IntersectionObserver' in window)) { pending.forEach(render); return; }
  const io = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (!entry.isIntersecting) return;
      const diagram = pending.find(d => d.fig === entry.target);
      if (diagram) { render(diagram); io.unobserve(entry.target); }
    });
  }, { rootMargin: '600px 0px' });
  pending.forEach(d => io.observe(d.fig));
}

async function fontsReady() {
  if (!document.fonts || !document.fonts.load) return;
  // 📝 Labels are measured once, so every face they use must be loaded first:
  //    `fonts.ready` only covers faces already requested by the page, and the
  //    italic keywords / monospace chips are usually not among them yet.
  const faces = [
    '400 14px "Space Grotesk"', 'italic 400 14px "Space Grotesk"', '600 14px "Space Grotesk"',
    '700 14px "Space Grotesk"', '500 12px "JetBrains Mono"'
  ];
  const loading = Promise.all(faces.map(face => document.fonts.load(face).catch(() => null))).then(() => document.fonts.ready);
  await Promise.race([loading, new Promise(resolve => setTimeout(resolve, 3000))]);
}

async function loadMermaid() {
  // 📝 A dynamic import: when the CDN is unreachable the figures and their
  //    "Open in Stately" links are still built, with a note in place of the chart.
  try {
    const module = await import(MERMAID_URL);
    return module.default;
  } catch (_) {
    return null;
  }
}

async function start() {
  const fences = collectFences();
  if (!fences.length && !document.querySelector('.stately[data-machine]')) return;
  const embedsReady = collectEmbeds(); // fetches the asset while Mermaid and the fonts load
  document.body.appendChild(lb);
  const [loaded] = await Promise.all([loadMermaid(), fontsReady()]);
  mermaid = loaded;
  if (mermaid) {
    configureMermaid();
    watchTheme();
  }
  fences.forEach(render);
  const embeds = await embedsReady;
  if (mermaid) observe(embeds);
  else embeds.forEach(render); // every marker gets its note and link at once
}

const ready = start();

window.xsmDiagrams = {
  ready,
  figures,
  /** Render every chart on the page now (tooling; the page itself is lazy). */
  renderAll: () => ready.then(() => Promise.all(figures.filter(d => d.source).map(render))),
  /** Replace one figure's source and redraw it (tooling: layout tuning). */
  renderInto: (key, source) => ready.then(() => {
    const diagram = figures.find(d => d.key === key);
    if (!diagram) throw new Error('unknown diagram ' + key);
    diagram.source = source; diagram.pending = null;
    diagram.fig.classList.add('is-pending');
    return render(diagram);
  })
};
